package com.volna.profile_service.entity;import jakarta.persistence.*;import java.util.UUID;@Entity @Table(name="profile_restaurant_access",uniqueConstraints=@UniqueConstraint(name="uk_profile_access_user",columnNames="auth_user_id"))public class ProfileRestaurantAccess{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(name="restaurant_id",nullable=false)UUID restaurantId;@Column(name="auth_user_id",nullable=false,unique=true)UUID authUserId;public UUID getRestaurantId(){return restaurantId;}public UUID getAuthUserId(){return authUserId;}}
